            @Vertical.canceled += instance.OnVertical;
        }

        /// <summary>
        /// Removes <see cref="InputAction.started"/>, <see cref="InputAction.performed"/> and <see cref="InputAction.canceled"/> callbacks provided via <param cref="instance" /> on all input actions contained in this map.
        /// </summary>
        /// <remarks>
        /// Calling this method when <paramref name="instance" /> have not previously been registered has no side-effects.
        /// </remarks>
        /// <seealso cref="AardActions" />
        private void UnregisterCallbacks(IAardActions instance)
        {
            @MoveObject.started -= instance.OnMoveObject;
            @MoveObject.performed -= instance.OnMoveObject;
            @MoveObject.canceled -= instance.OnMoveObject;
            @Release.started -= instance.OnRelease;
            @Release.performed -= instance.OnRelease;
            @Release.canceled -= instance.OnRelease;
            @Vertical.started -= instance.OnVertical;
            @Vertical.performed -= instance.OnVertical;
            @Vertical.canceled -= instance.OnVertical;
        }

        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="AardActions.UnregisterCallbacks(IAardActions)" />.
        /// </summary>
        /// <seealso cref="AardActions.UnregisterCallbacks(IAardActions)" />
        public void RemoveCallbacks(IAardActions instance)
        {
            if (m_Wrapper.m_AardActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="AardActions.AddCallbacks(IAardActions)" />
        /// <seealso cref="AardActions.RemoveCallbacks(IAardActions)" />
        /// <seealso cref="AardActions.UnregisterCallbacks(IAardActions)" />
        public void SetCallbacks(IAardActions instance)
        {
            foreach (var item in m_Wrapper.m_AardActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_AardActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
    }
